const changed = [];
const failed = [];
for (const name of ['Run Pass 1 (Tables)', 'Run Pass 2 (Links)']) {
  if (!$(name).isExecuted) continue;
  const results = $(name).all();
  const ops = $(name === 'Run Pass 1 (Tables)' ? 'List Pass 1 Changes' : 'List Pass 2 Changes').all();
  results.forEach((r, i) => (ok(r.json) ? changed : failed).push(ops[i].json.label + (ok(r.json) ? '' : ' — ' + httpProblem(r.json))));
}
const seedPlan = $('Plan Settings Seed').first().json;
if ($('Create Settings Row').isExecuted) (ok($('Create Settings Row').first().json) ? changed : failed).push('seed Settings row');
const needsYou = [];
if (cmp) {
  if (cmp.missingTables.length) needsYou.push((apply ? 'Still missing tables: ' : 'Would create tables: ') + cmp.missingTables.join(', '));
  if (cmp.missingFields.length) needsYou.push((apply ? 'Still missing fields: ' : 'Would add fields: ') + cmp.missingFields.join(', '));
  if (cmp.mismatches.length) needsYou.push('Field types differ from the design (not changed): ' + cmp.mismatches.join('; '));
